<?php require 'api/db.php'; $tenant_id = 2; $stmt = $pdo->prepare('SELECT id, username, data, role, status FROM users WHERE tenant_id = ?'); $stmt->execute([$tenant_id]); $rows = $stmt->fetchAll(PDO::FETCH_ASSOC); $parsed_rows = []; foreach ($rows as $r) { if ($r['data']) { $parsed_rows[] = json_decode($r['data'], true); } else { $parsed_rows[] = ['id' => 'u_admin_default', 'username' => $r['username'], 'password' => '', 'fullName' => '???? ?????? ('.$r['username'].')', 'roleId' => 'role_admin_default', 'warehouse' => 'all', 'status' => $r['status'] ?? 'active', 'isSystem' => ($r['role'] === 'admin')]; } } echo json_encode($parsed_rows, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE); ?>
